def solve(values):
    # Split the input into words
    words = values.split()
    # Rotate each nonempty word left by 1 position modulo its length
    for i in range(len(words)):
        word = words[i]
        if len(word) == 0:
            continue
        words[i] = word[1:] + word[0]
    # Rejoin with single spaces
    return ' '.join(words)
```

